ROUTE_POLICIES = tuple(
    RoutePolicy(method, path, source, function, policy_type, permissions, note)
    for (method, path, source, function, policy_type, permissions, note) in _ROUTE_POLICY_ROWS
)

# 以 (method, path) 为键的只读索引；数据保证该键唯一。
ROUTE_POLICY_BY_KEY = MappingProxyType(
    {(policy.method, policy.path): policy for policy in ROUTE_POLICIES}
)

# 5 分钟内输过当前密码才可执行：所有真实删除与已批准的高风险变更。
# 登录本身会记录一次近期确认；超过 5 分钟后由全局授权器在进入处理函数前拦截。
RECENT_REAUTH_ROUTE_KEYS = frozenset(
    (policy.method, policy.path)
    for policy in ROUTE_POLICIES
    if policy.method == "DELETE"
) | frozenset(
    {
        ("POST", "/api/bills/{bill_id}/refund"),
        (
            "POST",
            "/api/patients/{patient_identity}/member-account/refund",
        ),
        ("POST", "/api/recycle-bin/restore"),
        ("POST", "/api/return-visits/batch-delete"),
        ("POST", "/api/staff-members/{staff_id}/reinstate"),
        ("POST", "/api/users/{user_id}/system-admin/grant"),
        ("POST", "/api/users/{user_id}/system-admin/revoke"),
    }
)
